class Logger {
  private static instance: Logger;
  private constructor() {}

  static getInstance(): Logger {
    if (!Logger.instance) {
      Logger.instance = new Logger();
    }
    return Logger.instance;
  }

  log(msg: string): void {
    console.log(`[LOG] ${msg}`);
  }
}

interface SortStrategy {
  sort(data: number[]): number[];
}
class BubbleSort implements SortStrategy {
  sort(data: number[]): number[] {
    /* bubble sort logic */
    return data;
  }
}
class Sorter {
  constructor(private strategy: SortStrategy) {}
  execute(data: number[]): number[] {
    return this.strategy.sort(data);
  }
}

interface Command { execute(): void; undo(): void; }
class LightOnCommand implements Command {
  constructor(private light: Light) {}
  execute() { this.light.turnOn(); }
  undo() { this.light.turnOff(); }
}
class RemoteControl {
  private history: Command[] = [];
  press(cmd: Command) {
    cmd.execute();
    this.history.push(cmd);
  }
}

class QueryBuilder {
  private query: string[] = ['SELECT'];
  columns(cols: string[]): this {
    this.query.push(cols.join(', ')); return this;
  }
  from(table: string): this {
    this.query.push(`FROM ${table}`); return this;
  }
  where(cond: string): this {
    this.query.push(`WHERE ${cond}`); return this;
  }
  build() { return this.query.join(' '); }
}

