type Next = () => Promise<void>;
type Middleware = (ctx: Context, next: Next) => Promise<void>;
class Pipeline {
  private stack: Middleware[] = [];
  use(mw: Middleware): void {
    this.stack.push(mw);
  }
  async execute(ctx: Context): Promise<void> {
    const run = (i: number): Promise<void> =>
      i < this.stack.length
        ? this.stack[i](ctx, () => run(i + 1))
        : Promise.resolve();
    return run(0);
  }
}

class Observable<T> {
  constructor(private subscribeFn: (obs: Observer<T>) => void) {}
  subscribe(obs: Observer<T>): void {
    this.subscribeFn(obs);
  }
  pipe<R>(op: (src: Observable<T>) => Observable<R>): Observable<R> {
    return op(this);
  }
  static of<T>(...items: T[]): Observable<T> {
    return new Observable(obs => {
      items.forEach(i => obs.next(i));
      obs.complete();
    });
  }
}

